def load_seed(path: Path) -> dict[str, np.ndarray | float | str]:
    with np.load(path) as data:
        w = np.asarray(data["w"], dtype=float)
        if "w_base" in data.files:
            w_base = np.asarray(data["w_base"], dtype=float)
        elif w.ndim == 1:
            # Legacy heatmap cubes used one common omega axis and did not save
            # the redundant w_base key.
            w_base = w.copy()
        elif w.ndim == 2 and np.allclose(w, w[0], rtol=0.0, atol=1.0e-12):
            w_base = np.asarray(w[0], dtype=float).copy()
        else:
            raise KeyError(
                f"{path}: missing w_base for a genuinely row-local omega grid"
            )
        return {
            "k": np.asarray(data["k"], dtype=float),
            "w": w,
            "w_base": w_base,
            "a": np.asarray(data["A"], dtype=float),
            "res": np.asarray(data["ReS"], dtype=float),
            "ims": np.asarray(data["ImS"], dtype=float),
            "sigma0": float(data["sigma0"]),
            "mass": float(data["mass"]),
            "eta": float(data["eta"]),
            "convention": str(data["a_convention"]),
            "mu_up": float(data["mu_up"]),
            "mu_dn": float(data["mu_dn"]) if "mu_dn" in data.files else float(data["mu_down"]),
        }


def occupied_nk(a: np.ndarray, w: np.ndarray) -> np.ndarray:
    a = np.asarray(a, dtype=float)
    w = np.asarray(w, dtype=float)
    if w.ndim == 1:
        mask = w <= 0.0
        return np.trapezoid(a[:, mask], w[mask], axis=1)
    return np.asarray(
        [
            np.trapezoid(a[i, w[i] <= 0.0], w[i, w[i] <= 0.0])
            for i in range(a.shape[0])
        ],
        dtype=float,
    )


def row_sum_rule(a: np.ndarray, w: np.ndarray) -> np.ndarray:
    a = np.asarray(a, dtype=float)
    w = np.asarray(w, dtype=float)
    if w.ndim == 1:
        return np.trapezoid(a, w, axis=1)
    return np.asarray(
        [np.trapezoid(a[i], w[i]) for i in range(a.shape[0])],
        dtype=float,
    )


def density(k: np.ndarray, nk: np.ndarray) -> float:
    return float(np.trapezoid(np.asarray(k) * np.asarray(nk), np.asarray(k)))


def _recon_linear() -> bool:
    """SIGMA_RECON_LINEAR: sostituisce PCHIP con interpolazione lineare nelle due
    ricostruzioni della Sigma sparsa (in omega da w_eval, in k da k_sparse).
    Diagnostico: se il risultato cambia, il campionamento non e' sufficiente;
    se non cambia, la ricostruzione e' adeguata e l'errore sta altrove.
    In k np.interp CLAMPA ai bordi invece di estrapolare come PchipInterpolator
    (extrapolate=True), il che e' anche piu' prudente oltre l'ultimo nodo."""
    return str(os.environ.get("SIGMA_RECON_LINEAR", "0")).strip().lower() not in {
        "", "0", "false", "no", "off"
    }


def density_with_contact_tail(
    k: np.ndarray,
    nk: np.ndarray,
    enabled: bool,
    fit_min: float = 10.0,
    fit_max_fraction: float = 0.92,
    contact_override: float = np.nan,
    contact_tail_start: float = np.nan,
) -> tuple[float, float, float, float]:
    """Return total, captured, extrapolated tail, and fitted contact.

    In the present two-dimensional normalization, n(k)=C/k^4 contributes
    C/(2*k_max^2) beyond the last momentum row. Nothing is rescaled.
    """
    k = np.asarray(k, dtype=float)
    nk = np.asarray(nk, dtype=float)
    captured = density(k, nk)
    if not enabled:
        return captured, captured, 0.0, float("nan")
    if np.isfinite(float(contact_override)):
        contact = float(contact_override)
    else:
        lo = max(float(fit_min), 0.70 * float(k[-1]))
        hi = float(fit_max_fraction) * float(k[-1])
        mask = (k >= lo) & (k <= hi) & np.isfinite(nk) & (nk >= 0.0)
        if np.count_nonzero(mask) < 3:
            raise RuntimeError(
                f"contact-tail fit has fewer than three rows in [{lo:g},{hi:g}]"
            )
        contact = float(np.median(k[mask] ** 4 * nk[mask]))
    if np.isfinite(float(contact_tail_start)):
        tail_start = float(contact_tail_start)
        if not (float(k[0]) < tail_start <= float(k[-1])):
            raise RuntimeError(
                f"contact tail start {tail_start:g} outside k support "
                f"[{k[0]:g},{k[-1]:g}]"
            )
        core_points = np.unique(
            np.concatenate((k[k < tail_start], np.asarray([tail_start])))
        )
        captured = float(
            np.trapezoid(
                core_points * np.interp(core_points, k, nk), core_points
            )
        )
        tail = contact / (2.0 * tail_start**2)
    else:
        tail = contact / (2.0 * float(k[-1]) ** 2)
    return captured + tail, captured, tail, contact


def pair_contact_from_shifted_table(
    q: np.ndarray, omega: np.ndarray, a_pair: np.ndarray
) -> tuple[float, float]:
    """Return Delta_inf^2 and the fermion C=Delta_inf^2/4."""
    q = np.asarray(q, dtype=float)
    omega = np.asarray(omega, dtype=float)
    a_pair = np.asarray(a_pair, dtype=float)
    occupied = omega <= 0.0
    if np.count_nonzero(occupied) < 2:
        raise RuntimeError("pair table has fewer than two occupied omega nodes")
    delta2 = -float(
        np.trapezoid(
            q * np.trapezoid(a_pair[:, occupied], omega[occupied], axis=1), q
        )
        / (2.0 * np.pi)
    )
    if not np.isfinite(delta2) or delta2 <= 0.0:
        raise RuntimeError(f"non-positive pair contact scale Delta_inf^2={delta2}")
    return delta2, 0.25 * delta2


def _two_pole_omega_row(
    w_base: np.ndarray,
    pole: float,
    pole_half_width: float,
    satellite: float,
    satellite_half_width: float,
    n_local: int,
) -> np.ndarray:
    """Budget-neutral omega row resolving both Dyson roots at high k."""
    w = np.unique(np.asarray(w_base, dtype=float))
    n_w = int(w.size)
    if n_w < 2:
        return w

    finite_centers = [value for value in (pole, satellite) if np.isfinite(value)]
    support_lo = min([float(w[0])] + [float(value) - 2.0 for value in finite_centers])
    support_hi = max([float(w[-1])] + [float(value) + 2.0 for value in finite_centers])

    def feature(center: float, half_width: float) -> np.ndarray:
        if not np.isfinite(center):
            return np.empty(0, dtype=float)
        # A narrow uniform feature followed by a large empty omega cell gives
        # the trapezoid rule a false triangular area.  Logarithmic shoulders
        # resolve the Lorentzian core and carry its decay continuously to both
        # global boundaries with the same fixed row budget.
        n_side = max(4, (int(n_local) - 1) // 2)
        # The physical/numerical Lorentzian width is O(1e-3).  Starting the
        # geometric shoulder at O(1e-3) leaves one oversized triangle across
        # the peak; start at 1e-4 or finer so the trapezoidal row measure is
        # genuinely converged without any post-hoc row normalization.
        core = max(min(float(half_width) / 256.0, 1.0e-5), 1.0e-7)
        span = max(center - support_lo, support_hi - center, float(half_width))
        offsets = np.geomspace(core, span, n_side)
        return np.unique(
            np.clip(
                np.concatenate((center - offsets, np.asarray([center]), center + offsets)),
                support_lo,
                support_hi,
            )
        )

    zero = w[np.abs(w) <= 0.20]
    primary = feature(float(pole), max(float(pole_half_width), 0.05))
    secondary = feature(float(satellite), max(float(satellite_half_width), 0.05))
    mandatory = np.unique(
        np.concatenate((np.asarray([support_lo, support_hi, 0.0]), primary, secondary))
    )
    budget = max(0, n_w - mandatory.size)
    if zero.size > budget:
        take = np.round(np.linspace(0, zero.size - 1, budget)).astype(int)
        zero = zero[take]
    anchors = np.unique(np.concatenate((mandatory, zero)))
    remaining = np.setdiff1d(w, anchors, assume_unique=False)
    budget = n_w - anchors.size
    if budget > 0 and remaining.size:
        take = np.round(np.linspace(0, remaining.size - 1, budget)).astype(int)
        anchors = np.unique(np.concatenate((anchors, remaining[take])))
    if anchors.size < n_w:
        remaining = np.setdiff1d(w, anchors, assume_unique=False)
        anchors = np.unique(np.concatenate((anchors, remaining[: n_w - anchors.size])))
    return np.asarray(np.sort(anchors)[:n_w], dtype=float)


_SIGMA_WORKER_CTX: dict = {}


